/* OMAR CIRCUIT LAB — pages: dashboard, component library & datasheets, medical lab, PCB studio, 3D workbench,
   AI copilot, engineering notebook, learning centre, project manager, settings & about */
'use strict';
(() => {
const { $, $$, esc, el, fmt } = OCL, UI = OCL.ui, I = (...a) => UI.icon(...a), V = UI.views;
const thumb = key => { try { const d = OCL.buildTemplate(key); let x0 = 1e9, y0 = 1e9, x1 = -1e9, y1 = -1e9; d.components.forEach(c => { x0 = Math.min(x0, c.x - 50); y0 = Math.min(y0, c.y - 50); x1 = Math.max(x1, c.x + 50); y1 = Math.max(y1, c.y + 50); });
  const cm = Object.fromEntries(d.components.map(c => [c.id, c])), wires = d.wires.map(w => { const a = OCL.editor.pinPos(cm[w.a.c], w.a.p), b = OCL.editor.pinPos(cm[w.b.c], w.b.p), pts = [a, ...(w.pts || []), b]; let s = `M${a[0]} ${a[1]}`; for (let i = 1; i < pts.length; i++) s += `H${pts[i][0]}V${pts[i][1]}`; return `<path d="${s}"/>`; }).join('');
  return `<svg viewBox="${x0} ${y0} ${x1 - x0} ${y1 - y0}" preserveAspectRatio="xMidYMid meet"><g fill="none" stroke="#2f7f9c" stroke-width="2.5">${wires}</g><g fill="none" stroke="#9fd8ec" stroke-width="3">${d.components.map(c => `<g transform="translate(${c.x},${c.y}) rotate(${c.rot * 90})" class="sym">${OCL.defs[c.type].symbol(c).replace(/<text[^>]*>.*?<\/text>/g, '')}</g>`).join('')}</g></svg>`; } catch (e) { return ''; } };

/* ---------------- DASHBOARD ---------------- */
V.dashboard = async host => {
  const recentIds = (await OCL.db.get('kv', 'recent')) || [], all = await OCL.db.all('projects'), recent = recentIds.map(id => all.find(p => p.id === id)).filter(Boolean).slice(0, 5), hist = ((await OCL.db.get('kv', 'simhistory')) || []).slice(0, 6);
  const qa = [['New Project', 'Blank schematic or template', 'plus', () => UI.newProjectDialog()], ['Open Project', 'Saved in this browser', 'open', () => UI.show('projects')], ['Medical Templates', 'ECG, SpO₂, thermometer…', 'heart', () => UI.show('medical')], ['Component Library', OCL.partsList().length + ' parts + datasheets', 'lib', () => UI.show('library')], ['AI Engineering Copilot', 'Local, circuit-aware', 'bot', () => UI.show('copilot')], ['PCB Design Studio', 'Layout · DRC · Gerber', 'pcb', () => UI.show('pcb')], ['3D Workbench', 'Exploded assembly', 'cube', () => UI.show('workbench')], ['Engineering Notebook', 'Notes · revisions · report', 'book', () => UI.show('notebook')], ['Learning Centre', 'Guided 12-step lessons', 'grad', () => UI.show('learning')]];
  host.innerHTML = `<div class="page"><div class="hero"><svg class="art" viewBox="0 0 460 260"><g fill="none" stroke="#22d3ee" stroke-width="1.4" opacity=".55"><path d="M20 180h80l20-50 30 100 30-140 25 90h60l15-30 15 30h145"/><path d="M60 60h120v40h80v-60h120" stroke="#3b82f6"/><circle cx="180" cy="60" r="4" fill="#22d3ee"/><circle cx="260" cy="100" r="4" fill="#3b82f6"/><rect x="300" y="20" width="60" height="40" rx="6"/><path d="M300 30h-10m10 10h-10m10 10h-10m70-20h10m-10 10h10m-10 10h10"/></g></svg>
    <h1><span>OMAR CIRCUIT LAB</span></h1><p style="font-size:15px;color:#b8c5da;margin:0 0 6px">Medical Engineering Design, Electronics Simulation &amp; 3D Prototyping Studio</p><p class="signature">Designed &amp; Developed by <b>Eng. Omar Abdalla</b> · KMTC Makindu Campus</p>
    <div class="row wrap" style="margin-top:16px"><button class="btn primary" id="d-cont">${I('circuit')} Continue “${esc(OCL.state.project.name)}”</button><button class="btn" id="d-new">${I('plus')} New project</button><button class="btn" id="d-ecg">${I('heart')} Try the ECG front end</button></div></div>
    <div class="qa" id="d-qa">${qa.map((q, i) => `<div class="card click" data-i="${i}"><div class="ic">${I(q[2])}</div><b>${q[0]}</b><span>${q[1]}</span></div>`).join('')}</div>
    <h3 style="margin-top:22px">Sample projects</h3><div class="grid g4">${OCL.SAMPLE_KEYS.map(k => { const t = OCL.templates[k]; return `<div class="card click sample" data-t="${k}"><div class="thumb">${thumb(k)}</div><div class="row"><b class="grow">${esc(t.title)}</b></div><span class="small muted">${esc(t.summary)}</span><div class="row"><span class="pill ${t.medical ? 'cyan' : ''}">${esc(t.tag)}</span>${t.medical ? '<span class="pill">Educational</span>' : ''}</div></div>`; }).join('')}</div>
    <div class="grid g2" style="margin-top:22px"><div class="card"><h3>${I('folder')} Recent projects</h3><div class="list">${recent.length ? recent.map(p => `<div class="li"><div class="grow"><b>${esc(p.name)}</b><div class="small muted">${new Date(p.modified).toLocaleString()} · ${p.sheets.reduce((s, x) => s + x.components.length, 0)} parts</div></div><button class="btn sm" data-open="${p.id}">Open</button></div>`).join('') : '<div class="empty">No saved projects yet — press Save (Ctrl+S) in the designer.</div>'}</div></div>
    <div class="card"><h3>${I('play')} Simulation history</h3><div class="list">${hist.length ? hist.map(h => `<div class="li"><span class="sev ${h.ok ? 'sev-low' : 'sev-critical'}">${h.ok ? 'OK' : 'FAIL'}</span><div class="grow"><b>${esc(h.project)}</b><div class="small muted">${esc(h.kind)}${h.ms !== undefined ? ' · ' + h.ms + ' ms' : ''}${h.msg ? ' · ' + esc(h.msg.slice(0, 80)) : ''}</div></div><span class="small muted">${new Date(h.at).toLocaleTimeString()}</span></div>`).join('') : '<div class="empty">Run a simulation to build history.</div>'}</div></div></div></div>`;
  $$('#d-qa .card').forEach(c => c.onclick = () => qa[+c.dataset.i][3]()); $$('[data-t]', host).forEach(c => c.onclick = () => UI.openTemplate(c.dataset.t));
  $('#d-cont').onclick = () => UI.show('designer'); $('#d-new').onclick = () => UI.newProjectDialog(); $('#d-ecg').onclick = () => UI.openTemplate('ecg');
  $$('[data-open]', host).forEach(b => b.onclick = async () => { UI.setProject(OCL.validateProjectJSON(await OCL.db.get('projects', b.dataset.open))); UI.show('designer'); });
};

/* ---------------- COMPONENT LIBRARY ---------------- */
UI.libCat = 'All'; UI.libSel = 'res'; UI.cmp = [];
const libPage = host => {
  const q = (UI.libQ || '').toLowerCase(), cat = UI.libCat || 'All';
  const list = OCL.partsList().filter(p => (cat === 'All' || (cat === '★' ? UI.favs.has(p.key) : OCL.partCat(p) === cat)) && (!q || (p.name + ' ' + (p.tags || '') + ' ' + (p.ds.part || '') + ' ' + (p.ds.mfr || '') + ' ' + p.key).toLowerCase().includes(q)));
  const title = { Microcontrollers: 'Microcontrollers', Power: 'Power Electronics', Sensors: 'Sensors', Medical: 'Medical Electronics parts' }[cat] || 'Component Library & Datasheets';
  host.innerHTML = `<div class="page" style="max-width:1400px"><div class="row"><h2 class="grow">${title}</h2><button class="btn" id="l-custom">${I('plus')} Custom component</button><button class="btn" id="l-cmp" ${UI.cmp.length < 2 ? 'disabled' : ''}>Compare (${UI.cmp.length})</button></div>
    <p class="muted">Search by name or part number. <span class="pill sim">SIM</span> full simulation model · <span class="pill partial">PARTIAL</span> partial model · <span class="pill cat">CATALOG</span> placement & datasheet only. Unavailable specifications are marked — never assumed.</p>
    <input class="inp" id="l-q" placeholder="Search: resistor, 1N4007, LM358, oxygen, ESP32…" value="${esc(UI.libQ || '')}" style="max-width:520px">
    <div class="chips">${['All', '★', ...OCL.CATS].map(c => `<span class="chip ${c === cat ? 'on' : ''}" data-c="${c}">${c === '★' ? '★ Favourites' : c}</span>`).join('')}</div>
    <div class="lib-layout"><div class="lib-grid">${list.map(p => `<div class="lib-card ${p.key === UI.libSel ? 'on' : ''}" data-k="${p.key}"><div class="mini">${UI.miniSym(p.key)}</div><div style="min-width:0"><b>${esc(p.name)}</b><div class="small muted">${esc(p.ds.part || p.ds.mfr || OCL.partCat(p))}</div><div class="tags">${OCL.defs[p.base].sim === 'full' ? '<span class="pill sim">SIM</span>' : OCL.defs[p.base].sim === 'partial' ? '<span class="pill partial">PARTIAL</span>' : '<span class="pill cat">CATALOG</span>'}${UI.favs.has(p.key) ? '<span class="pill">★</span>' : ''}${UI.cmp.includes(p.key) ? '<span class="pill cyan">compare</span>' : ''}</div></div></div>`).join('') || '<div class="empty">No parts match your search.</div>'}</div>
    <div class="card ds-sticky" id="l-ds"></div></div></div>`;
  const ds = () => { const p = OCL.parts[UI.libSel] || OCL.customParts[UI.libSel]; if (!p) { $('#l-ds').innerHTML = '<p class="muted">Select a part.</p>'; return; }
    $('#l-ds').innerHTML = `<div class="mini" style="width:100%;height:90px;margin-bottom:8px">${UI.miniSym(p.key)}</div>${UI.datasheetHTML(p.key)}<div class="row wrap" style="margin-top:12px"><button class="btn primary sm" id="l-place">${I('plus')} Place in designer</button><button class="btn sm" id="l-fav">${I('star')} ${UI.favs.has(p.key) ? 'Unfavourite' : 'Favourite'}</button><button class="btn sm" id="l-addcmp">${UI.cmp.includes(p.key) ? 'Remove from compare' : 'Add to compare'}</button><button class="btn sm" id="l-attach">${I('note')} Attach to project</button>${OCL.customParts[p.key] ? '<button class="btn sm danger" id="l-delc">Delete custom</button>' : ''}</div>`;
    $('#l-place').onclick = () => { UI.show('designer'); OCL.editor.startPlace(p.key); }; $('#l-fav').onclick = () => { UI.toggleFav(p.key); libPage(host); };
    $('#l-addcmp').onclick = () => { UI.cmp = UI.cmp.includes(p.key) ? UI.cmp.filter(x => x !== p.key) : [...UI.cmp, p.key].slice(-4); libPage(host); };
    $('#l-attach').onclick = () => { OCL.state.project.notes.unshift({ id: OCL.uid('n'), type: 'documentation', text: `Datasheet: ${p.name}${p.ds.part ? ' (' + p.ds.part + ')' : ''}${p.ds.link ? ' — ' + p.ds.link : ''}`, at: Date.now() }); OCL.emit('dirty'); OCL.toast('Datasheet reference attached to the project notebook', 'ok'); };
    if ($('#l-delc')) $('#l-delc').onclick = async () => { if (await OCL.confirm('Delete custom component', `Delete “${p.name}”? Placed instances will become invalid.`, 'Delete', true)) { delete OCL.customParts[p.key]; await OCL.db.put('kv', 'customParts', OCL.customParts); UI.libSel = 'res'; libPage(host); } }; };
  ds();
  $('#l-q').oninput = e => { UI.libQ = e.target.value; clearTimeout(UI._lq); UI._lq = setTimeout(() => { libPage(host); const i = $('#l-q'); i.focus(); i.setSelectionRange(i.value.length, i.value.length); }, 200); };
  $$('.chip', host).forEach(c => c.onclick = () => { UI.libCat = c.dataset.c; libPage(host); });
  $$('.lib-card', host).forEach(c => c.onclick = () => { UI.libSel = c.dataset.k; $$('.lib-card', host).forEach(x => x.classList.toggle('on', x === c)); ds(); });
  $('#l-cmp').onclick = () => compare(); $('#l-custom').onclick = () => customDialog(host);
};
V.library = V.mcu = V.power = V.sensors = libPage;
function compare() {
  const ps = UI.cmp.map(k => OCL.parts[k] || OCL.customParts[k]).filter(Boolean); const F = [['Manufacturer', 'mfr'], ['Part number', 'part'], ['Operating voltage', 'vop'], ['Maximum voltage', 'vmax'], ['Maximum current', 'imax'], ['Power', 'pwr'], ['Tolerance', 'tol'], ['Package', 'pkg'], ['Temperature', 'temp'], ['Applications', 'apps']];
  OCL.modal({ title: 'Compare components', wide: true, body: `<table class="cmp-table"><tr><th></th>${ps.map(p => `<th>${esc(p.name)}</th>`).join('')}</tr>${F.map(([l, k]) => `<tr><td><b>${l}</b></td>${ps.map(p => `<td>${p.ds[k] ? esc(p.ds[k]) : '<i class="muted">Not specified</i>'}</td>`).join('')}</tr>`).join('')}<tr><td><b>Characteristics</b></td>${ps.map(p => `<td>${(p.ds.elec || []).map(esc).join('<br>') || '<i class="muted">Not specified</i>'}</td>`).join('')}</tr><tr><td><b>Simulation</b></td>${ps.map(p => `<td>${OCL.defs[p.base].sim}</td>`).join('')}</tr></table>` });
}
async function customDialog(host) {
  const body = el(`<div><p class="muted small">Custom components are catalog parts (no simulation model). They get a generic IC symbol with your pins, a DIP footprint and a datasheet card.</p>
    <label class="fld"><span>Name</span><input class="inp" id="cc-n" placeholder="e.g. HX711 load-cell amplifier"></label><label class="fld"><span>Pin names (comma separated, 2–24)</span><input class="inp mono" id="cc-p" placeholder="VCC, GND, DOUT, SCK, E+, E-"></label>
    <div class="grid g2"><label class="fld"><span>Category</span><select class="inp" id="cc-c">${OCL.CATS.filter(c => c !== 'Basic').map(c => `<option ${c === 'Custom' ? 'selected' : ''}>${c}</option>`).join('')}</select></label><label class="fld"><span>Manufacturer</span><input class="inp" id="cc-m"></label>
    <label class="fld"><span>Part number</span><input class="inp" id="cc-pn"></label><label class="fld"><span>Package / dimensions</span><input class="inp" id="cc-pk" placeholder="e.g. SOP-16, 10 × 6 mm"></label>
    <label class="fld"><span>Operating voltage</span><input class="inp" id="cc-v"></label><label class="fld"><span>Maximum current</span><input class="inp" id="cc-i"></label></div>
    <label class="fld"><span>Description / specifications</span><textarea class="inp" id="cc-d" rows="2"></textarea></label><label class="fld"><span>Datasheet URL (optional)</span><input class="inp" id="cc-l" placeholder="https://…"></label></div>`);
  const r = await OCL.modal({ title: 'Create custom component', body, actions: [{ label: 'Cancel', value: null }, { label: 'Create', kind: 'primary', value: m => { const g = s => m.querySelector(s).value.trim(); const pins = g('#cc-p').split(',').map(s => s.trim()).filter(Boolean);
    if (!g('#cc-n')) { OCL.toast('Enter a name', 'warn'); return false; } if (pins.length < 2 || pins.length > 24 || new Set(pins).size !== pins.length) { OCL.toast('Enter 2–24 unique pin names', 'warn'); return false; } const link = g('#cc-l'); if (link && !/^https?:\/\//.test(link)) { OCL.toast('Datasheet URL must start with http(s)://', 'warn'); return false; }
    return { name: g('#cc-n'), pins, cat: g('#cc-c'), ds: { desc: g('#cc-d') || 'User-defined component.', mfr: g('#cc-m'), part: g('#cc-pn'), pkg: g('#cc-pk'), vop: g('#cc-v'), imax: g('#cc-i'), link } }; } }] });
  if (!r) return; const key = 'custom_' + OCL.uid('');
  OCL.customParts[key] = { key, base: 'block', name: r.name, cat: r.cat, props: {}, pinNames: r.pins, label: r.name.slice(0, 10), tags: 'custom ' + r.name, ds: r.ds, custom: true };
  await OCL.db.put('kv', 'customParts', OCL.customParts); UI.libSel = key; UI.libCat = 'All'; OCL.toast('Custom component saved to your library', 'ok'); libPage(host);
}

/* ---------------- MEDICAL LAB ---------------- */
UI.medSel = 'ecg';
V.medical = host => {
  const t = OCL.templates[UI.medSel] || OCL.templates.ecg, live = OCL.state.project.template === t.key && OCL.sim.readings && t.live ? t.live(OCL.sim.readings, OCL.sim) : '';
  host.innerHTML = `<div class="page" style="max-width:1400px"><h2>Medical Engineering Lab</h2><p class="muted">Biomedical electronics prototypes with schematics, calculations, simulation, troubleshooting and 3D views. <b>All are educational prototypes — not clinically validated medical devices.</b></p>
    <div class="med-layout"><div class="med-list">${OCL.MEDICAL_KEYS.map(k => { const x = OCL.templates[k]; return `<div class="card click ${k === t.key ? 'on' : ''}" data-k="${k}"><h3 style="margin:0">${I(x.icon)} ${esc(x.title)}</h3><p class="small muted" style="margin:6px 0 0">${esc(x.summary)}</p></div>`; }).join('')}</div>
    <div class="card"><div class="row wrap"><h2 class="grow" style="margin:0">${esc(t.title)}</h2><button class="btn primary" id="m-open">${I('circuit')} Open schematic</button><button class="btn" id="m-sim">${I('play')} Open &amp; simulate</button><button class="btn" id="m-3d">${I('cube')} 3D view</button><button class="btn" id="m-learn">${I('grad')} Guided lesson</button></div>
      ${OCL.SAFETY_HTML}
      <div class="sect"><h4>Block diagram</h4>${OCL.blockDiagramSVG(t.blocks)}</div>
      <div class="grid g2"><div class="sect"><h4>Working principle</h4><p>${esc(t.principle)}</p></div><div class="sect"><h4>Circuit schematic</h4><div style="height:200px;background:#0b111b;border:1px solid var(--line);border-radius:10px;overflow:hidden">${thumb(t.key)}</div></div></div>
      <div class="grid g2"><div class="sect"><h4>Engineering calculations</h4><ul>${t.calcs.map(c => `<li>${esc(c)}</li>`).join('')}</ul></div><div class="sect"><h4>Simulation results</h4>${live || `<p class="muted small">Open &amp; simulate this project to see live results here (values come from the simulator, not from this text).</p>`}</div></div>
      <div class="sect"><h4>Component list</h4>${bomTable(t.key)}</div>
      <div class="grid g2"><div class="sect"><h4>Troubleshooting guide</h4><ul>${t.trouble.map(c => `<li>${esc(c)}</li>`).join('')}</ul></div><div class="sect"><h4>Improvement suggestions</h4><ul>${t.improve.map(c => `<li>${esc(c)}</li>`).join('')}</ul></div></div></div></div></div>`;
  $$('.med-list .card', host).forEach(c => c.onclick = () => { UI.medSel = c.dataset.k; V.medical(host); });
  $('#m-open').onclick = () => UI.openTemplate(t.key); $('#m-sim').onclick = async () => { await UI.openTemplate(t.key); OCL.sim.run(); UI.showBottom('scope'); };
  $('#m-3d').onclick = async () => { await UI.openTemplate(t.key); OCL.pcb.sync(true); UI.show('workbench'); }; $('#m-learn').onclick = () => { UI.lesson = t.key; UI.show('learning'); };
};
function bomTable(key) { const d = OCL.buildTemplate(key), rows = {}; d.components.forEach(c => { const def = OCL.defs[c.type]; if (['ground', 'label', 'vcc', 'junction'].includes(c.type)) return; const p = OCL.parts[c.part]; const k = c.part + (def.value ? def.value(c) : ''); rows[k] = rows[k] || { refs: [], name: p.name, val: def.value ? def.value(c) : '' }; rows[k].refs.push(c.ref); });
  return `<table class="ptable"><tr><th>Ref</th><th>Part</th><th>Value</th></tr>${Object.values(rows).map(r => `<tr><td class="mono">${esc(r.refs.join(', '))}</td><td>${esc(r.name)}</td><td class="mono">${esc(r.val)}</td></tr>`).join('')}</table>`; }

/* ---------------- PCB STUDIO ---------------- */
V.pcb = host => {
  const pcb = OCL.pcb.ensure(); if (!pcb.parts.length && OCL.allComponents().length) OCL.pcb.sync(true);
  if (!host.dataset.built) { host.dataset.built = 1; host.classList.add('full'); }
  host.innerHTML = `<div class="pcb-layout"><div class="pcb-tools">${[['select', 'cursor', 'Select / move (R rotate)'], ['route', 'route', 'Route track'], ['via', 'via', 'Place via'], ['delete', 'trash', 'Delete track/via']].map(t => `<button class="tb ${OCL.pcb.tool === t[0] ? 'on' : ''}" data-t="${t[0]}" title="${t[2]}">${I(t[1])}<span>${t[2].split(' (')[0]}</span></button>`).join('')}<span class="tsep"></span>
    <button class="tb" id="pc-layer">${I('layers')}<span>Layer: <b>${OCL.pcb.layer}</b> (L)</span></button><span class="tsep"></span><button class="tb" id="pc-sync">${I('circuit')}<span>Update from schematic</span></button><button class="tb" id="pc-auto">${I('route')}<span>Auto-route (naive)</span></button><button class="tb" id="pc-drc">${I('shield')}<span>Run DRC</span></button><button class="tb" id="pc-fit">${I('fit')}<span>Fit</span></button><button class="tb" id="pc-fab">${I('export')}<span>Fabrication files</span></button><button class="tb" id="pc-3d">${I('cube')}<span>3D</span></button></div>
    <div class="pcb-canvas"><canvas id="pcb-cv"></canvas><div class="overlay-help">Hover a pad for pin info · click a pad to trace · drag parts · wheel zoom · Alt/middle-drag pan · Route: pad → bends → pad · L layer · Esc clears</div></div>
    <div class="pcb-side" id="pcb-side"></div></div>`;
  OCL.pcb.mount($('#pcb-cv')); OCL.pcb.analyze(); setTimeout(() => OCL.pcb.fit(), 30);
  $$('.pcb-tools [data-t]').forEach(b => b.onclick = () => { OCL.pcb.tool = b.dataset.t; OCL.pcb.route = null; $$('.pcb-tools [data-t]').forEach(x => x.classList.toggle('on', x === b)); });
  $('#pc-layer').onclick = () => { OCL.pcb.layer = OCL.pcb.layer === 'top' ? 'bottom' : 'top'; V.pcb(host); };
  $('#pc-sync').onclick = async () => { const re = pcb.tracks.length ? await OCL.confirm('Update from schematic', 'Re-place all footprints from the schematic layout? Existing tracks are kept but may no longer reach their pads.', 'Re-place all') : true; OCL.pcb.sync(re); OCL.pcb.analyze(); OCL.pcb.fit(); side(); };
  $('#pc-auto').onclick = () => { OCL.pcb.autoRoute(); side(); }; $('#pc-drc').onclick = () => { OCL.pcb.analyze(); OCL.pcb.draw(); side(); OCL.toast('DRC complete', 'ok'); }; $('#pc-fit').onclick = () => OCL.pcb.fit(); $('#pc-fab').onclick = UI.fabDialog; $('#pc-3d').onclick = () => UI.show('workbench');
  if (!UI._pcbHooks) { UI._pcbHooks = true; OCL.on('pcbsel', () => OCL.state.view === 'pcb' && UI.pcbSide && UI.pcbSide()); OCL.on('trace', () => { if (OCL.state.view === 'pcb') { OCL.pcb.draw(); UI.pcbSide && UI.pcbSide(); } });
    OCL.on('selection', () => { if (OCL.state.view === 'pcb' || OCL.state.view === 'workbench') { OCL.pcb.sel = OCL.state.sel; OCL.pcb.draw(); } }); } OCL.on('pcblayer', () => { const b = $('#pc-layer'); if (b) b.innerHTML = `${I('layers')}<span>Layer: <b>${OCL.pcb.layer}</b> (L)</span>`; });
  const side = () => { const s = $('#pcb-side'); if (!s) return; const d = OCL.pcb.drc || OCL.pcb.analyze(), st = pcb.settings, selC = OCL.findComp(OCL.pcb.sel);
    s.innerHTML = `<div class="banner">Educational PCB output. <b>Not verified as manufacturing-ready</b> — inspect exports in a Gerber viewer and with your fabricator.</div>
      <h4>Board</h4><div class="grid g2"><label class="fld"><span>Width (mm)</span><input class="inp mono" id="pb-w" value="${pcb.w}"></label><label class="fld"><span>Height (mm)</span><input class="inp mono" id="pb-h" value="${pcb.h}"></label></div>
      <h4>Rules</h4><div class="grid g2"><label class="fld"><span>Track width</span><input class="inp mono" id="pb-tw" value="${st.width}"></label><label class="fld"><span>Clearance</span><input class="inp mono" id="pb-cl" value="${st.clearance}"></label><label class="fld"><span>Min. width</span><input class="inp mono" id="pb-mw" value="${st.minWidth}"></label><label class="fld"><span>GND pour (bottom)</span><select class="inp" id="pb-gp"><option value="0">Off</option><option value="1" ${st.gndPour ? 'selected' : ''}>On</option></select></label></div>
      <h4>Layers</h4><div class="layer-grid">${[['top', 'Top copper'], ['bottom', 'Bottom copper'], ['silk', 'Silkscreen'], ['mask', 'Solder mask'], ['drill', 'Drill'], ['fab', 'Fabrication'], ['rats', 'Ratsnest'], ['padnums', 'Pad numbers'], ['pinnames', 'Pin names']].map(([k, l]) => `<label class="chk"><input type="checkbox" data-ly="${k}" ${OCL.pcb.layers[k] ? 'checked' : ''}> ${l}</label>`).join('')}</div>
      ${selC ? (() => { const pt = pcb.parts.find(p => p.cid === selC.id), opts = OCL.fpOptions(selC), po = OCL.pinout(selC, OCL.fpKey(selC, pt)), nl = OCL.netlist(); return `<h4>Selected: ${esc(selC.ref)}</h4><label class="fld"><span>Footprint</span><select class="inp" id="pb-fp">${opts.map(k => `<option value="${k}" ${OCL.fpKey(selC, pt) === k ? 'selected' : ''}>${esc((OCL.pcb.fpFor(selC, { fp: k }) || {}).name || k)}</option>`).join('')}</select></label>
        <table class="ptable"><tr><th>Pad</th><th>Name</th><th>Function</th><th>Net</th></tr>${po.pads.map(p => `<tr class="click" data-pad="${p.num}" ${OCL.pcb.selPad === selC.id + ':' + (p.num - 1) ? 'style="background:#0b2c38"' : ''}><td class="mono">${p.num}${p.num === 1 ? ' ●' : ''}</td><td class="mono">${esc(p.name)}</td><td class="small">${esc(p.func.split(' — ')[0])}</td><td class="mono small">${p.pin ? esc(nl.nets[nl.nodeOf[selC.id + ':' + p.pin]].name) : p.implicit ? '<span class="sev sev-medium">implicit</span>' : 'NC'}</td></tr>`).join('')}</table>
        ${po.generic ? '<p class="small"><span class="sev sev-medium">generic pinout</span> verify against your exact part’s datasheet.</p>' : '<p class="small muted">Pad numbers follow the manufacturer datasheet for this part and footprint. ● = pin 1 (square pad + silkscreen dot).</p>'}<p class="small muted">R rotates · click a pad to trace it.</p>`; })() : '<p class="small muted">Click a part to edit its footprint, or a pad to inspect and trace it.</p>'}
      <h4>Trace my circuit</h4><div id="pcb-trace">${OCL.trace.panelHTML()}</div>
      <h4>Design rule check</h4><p class="small">${d.totalConn - d.unrouted}/${d.totalConn} connections routed · ${pcb.tracks.length} tracks · ${pcb.vias.length} vias</p>
      <div>${d.issues.length ? d.issues.slice(0, 40).map(i => `<div class="hint sev-${i.sev}"><span class="sev sev-${i.sev}">${i.sev}</span> ${esc(i.msg)}</div>`).join('') : '<p class="sev sev-low">No DRC violations.</p>'}</div>
      <p class="muted small">Checks: unrouted nets, shorts, track–track/track–pad/pad–pad clearance, minimum width, courtyard overlap, board-edge clearance.</p>`;
    const num = (id, f) => { const i = $(id); i.onchange = () => { const v = parseFloat(i.value); if (!(v > 0)) return OCL.toast('Enter a positive number', 'warn'); f(v); OCL.emit('dirty'); OCL.pcb.analyze(); OCL.pcb.draw(); side(); }; };
    $$('[data-ly]', s).forEach(i => i.onchange = () => { OCL.pcb.layers[i.dataset.ly] = i.checked; OCL.pcb.draw(); });
    if ($('#pb-fp')) $('#pb-fp').onchange = e => { const pt = pcb.parts.find(p => p.cid === selC.id); pt.fp = e.target.value; OCL.pcb.changed(); side(); OCL.toast(`${selC.ref}: footprint ${OCL.pcb.fpFor(selC, pt).name}`, 'ok'); };
    $$('[data-pad]', s).forEach(r => r.onclick = () => { const n = +r.dataset.pad, p = OCL.pinout(selC, OCL.fpKey(selC, pcb.parts.find(q => q.cid === selC.id))).pads[n - 1]; OCL.pcb.selPad = selC.id + ':' + (n - 1); if (p.pin) OCL.trace.start(selC.id, p.pin); OCL.pcb.draw(); side(); });
    OCL.trace.bindPanel($('#pcb-trace'));
    num('#pb-w', v => pcb.w = v); num('#pb-h', v => pcb.h = v); num('#pb-tw', v => st.width = v); num('#pb-cl', v => st.clearance = v); num('#pb-mw', v => st.minWidth = v); $('#pb-gp').onchange = e => { st.gndPour = e.target.value === '1'; OCL.pcb.analyze(); OCL.pcb.draw(); side(); };
  };
  UI.pcbSide = side; side(); OCL.on('dirty', () => OCL.state.view === 'pcb' && UI.pcbSide && UI.pcbSide());
};
UI.fabDialog = () => { const P = OCL.pcb, d = P.analyze(), s = OCL.state.project.name.replace(/[^\w-]+/g, '_');
  const files = [['Top copper (F.Cu)', s + '-F_Cu.gbr', () => P.gerber('top')], ['Top silkscreen (F.SilkS)', s + '-F_SilkS.gbr', () => P.gerber('silk')], ['Bottom copper (B.Cu)', s + '-B_Cu.gbr', () => P.gerber('bottom')], ['Board outline (Edge.Cuts)', s + '-Edge_Cuts.gbr', () => P.gerber('outline')], ['Excellon drill', s + '.drl', () => P.drill()], ['Bill of materials', s + '-BOM.csv', () => OCL.bomCSV()], ['PCB layout (JSON)', s + '-pcb.json', () => JSON.stringify(OCL.state.project.pcb, null, 1)]];
  const body = el(`<div>${d.unrouted || d.issues.some(i => i.sev === 'critical') ? `<div class="errbox">DRC reports ${d.unrouted} unrouted connection(s) and ${d.issues.filter(i => i.sev === 'critical').length} critical issue(s). Files can be exported for review, but the board is incomplete.</div>` : ''}<div class="banner">RS-274X Gerber + Excellon generated by an educational exporter. Not included yet: solder mask, paste, silkscreen text and copper pours. <b>Not manufacturing-ready</b> — review in a Gerber viewer.</div>${files.map((f, i) => `<div class="li"><div class="grow"><b>${f[0]}</b><div class="small muted mono">${f[1]}</div></div><button class="btn sm" data-i="${i}">${I('export')} Export</button></div>`).join('')}</div>`);
  body.querySelectorAll('[data-i]').forEach(b => b.onclick = () => { const f = files[+b.dataset.i]; OCL.exportText(f[1], f[2]()); });
  OCL.modal({ title: 'Fabrication files', body, wide: true }); };

/* ---------------- 3D WORKBENCH (v2.1: split views, presets, layers, pins, trace) ---------------- */
UI.wb = { split: 'schematic', splitW: 42, side: true };
V.workbench = host => {
  if (!OCL.allComponents().length) { host.classList.remove('full'); host.innerHTML = `<div class="page"><h2>3D Workbench</h2><div class="empty">Your project has no components yet. Design a circuit or open a template first.<br><br><button class="btn primary" id="w-t">Open ECG template</button></div></div>`; $('#w-t').onclick = () => { UI.openTemplate('ecg').then(() => UI.show('workbench')); }; return; }
  host.classList.add('full'); const V3 = OCL.view3d, W = UI.wb; OCL.pcb.ensure(); if (!OCL.state.project.pcb.parts.length) OCL.pcb.sync(true); OCL.pcb.analyze(); V3.build(); V3.sel = OCL.state.sel;
  const views = [['top', 'Top'], ['bottom', 'Bottom'], ['front', 'Front'], ['back', 'Back'], ['left', 'Left'], ['right', 'Right'], ['iso', 'Iso']];
  host.innerHTML = `<div class="wb2 ${W.side ? '' : 'noside'}" id="wb2"><div class="wb-tools">
      <div class="seg">${views.map(v => `<button data-view="${v[0]}">${v[1]}</button>`).join('')}</div>
      <div class="seg"><button id="w-persp" class="${V3.ortho ? '' : 'on'}">Persp</button><button id="w-ortho" class="${V3.ortho ? 'on' : ''}">Ortho</button></div><span class="tsep"></span>
      <button class="tb ${V3.tool === 'orbit' ? 'on' : ''}" id="w-orbit">${I('rotate')}<span>Orbit</span></button><button class="tb ${V3.tool === 'move' ? 'on' : ''}" id="w-move">${I('cursor')}<span>Move part</span></button><button class="tb ${V3.snap ? 'on' : ''}" id="w-snap">${I('fit')}<span>Snap</span></button>
      <button class="tb ${OCL.state.traceMode ? 'on' : ''}" id="w-trace">${I('route')}<span>Trace</span></button><span class="tsep"></span>
      <button class="tb" id="w-exp">${I('explode')}<span>Explode</span></button><button class="tb" id="w-asm">${I('check')}<span>Assemble</span></button><span class="tsep"></span>
      <div class="seg" title="Split screen"><button data-split="none" class="${W.split === 'none' ? 'on' : ''}">3D only</button><button data-split="schematic" class="${W.split === 'schematic' ? 'on' : ''}">+ Schematic</button><button data-split="pcb" class="${W.split === 'pcb' ? 'on' : ''}">+ PCB 2D</button></div>
      <span class="sp"></span><button class="tb" id="w-fs">${I('fit')}<span>Full screen</span></button><button class="tb" id="w-side">${I('list')}<span>Panel</span></button></div>
    <div class="wb-body" style="--split:${W.split === 'none' ? 0 : W.splitW}%">
      <div class="wb-left" id="wb-left" ${W.split === 'none' ? 'hidden' : ''}></div><div class="wb-div" id="wb-div" ${W.split === 'none' ? 'hidden' : ''} title="Drag to resize"></div>
      <div class="wb-canvas"><canvas id="wb-cv"></canvas><div class="overlay-help">Drag orbit · Shift/right-drag pan · wheel zoom · W A S D / Q E fly (click canvas first) · hover a pad for pin info · click a pad to trace · nav-cube faces set the view</div></div>
      <div class="wb-side" id="wb-side"></div></div></div>`;
  V3.mount($('#wb-cv')); setTimeout(() => V3.fit(), 30);
  // split pane
  const left = $('#wb-left'); if (W.split === 'schematic') new OCL.SchPane(left); else if (W.split === 'pcb') { left.innerHTML = `<div class="pcb-mini"><canvas id="wb-pcb"></canvas><div class="pane-badge">PCB 2D · hover pads · click a pad to trace · drag parts (syncs to 3D)</div></div>`; OCL.pcb.mount($('#wb-pcb')); setTimeout(() => OCL.pcb.fit(), 40); }
  const div = $('#wb-div'); if (div) div.onmousedown = e => { e.preventDefault(); const body = host.querySelector('.wb-body'), r = body.getBoundingClientRect(); const mv = ev => { W.splitW = OCL.clamp((ev.clientX - r.left) / r.width * 100, 18, 70); body.style.setProperty('--split', W.splitW + '%'); }; const up = () => { window.removeEventListener('mousemove', mv); window.removeEventListener('mouseup', up); V3.draw(); OCL.pcb.draw(); }; window.addEventListener('mousemove', mv); window.addEventListener('mouseup', up); };
  $$('[data-view]', host).forEach(b => b.onclick = () => V3.setView(b.dataset.view));
  $('#w-persp').onclick = () => { V3.ortho = false; V.workbench(host); }; $('#w-ortho').onclick = () => { V3.ortho = true; V.workbench(host); };
  $('#w-orbit').onclick = () => { V3.tool = 'orbit'; V.workbench(host); }; $('#w-move').onclick = () => { V3.tool = 'move'; OCL.toast('Move: drag a component on the board (snaps to 0.635 mm). Changes sync to the PCB.'); V.workbench(host); };
  $('#w-snap').onclick = e => { V3.snap = !V3.snap; e.currentTarget.classList.toggle('on'); };
  $('#w-trace').onclick = e => { OCL.state.traceMode = !OCL.state.traceMode; e.currentTarget.classList.toggle('on'); if (!OCL.state.traceMode) OCL.trace.clear(); else OCL.toast('Trace: click any pad in 3D, PCB or schematic'); };
  $('#w-exp').onclick = () => V3.animateExplode(1); $('#w-asm').onclick = () => V3.animateExplode(0);
  $$('[data-split]', host).forEach(b => b.onclick = () => { W.split = b.dataset.split; V.workbench(host); });
  $('#w-side').onclick = () => { W.side = !W.side; $('#wb2').classList.toggle('noside', !W.side); setTimeout(() => { V3.draw(); OCL.pcb.draw(); }, 20); };
  $('#w-fs').onclick = () => { const el2 = $('#wb2'); if (document.fullscreenElement) document.exitFullscreen(); else if (el2.requestFullscreen) el2.requestFullscreen().catch(() => el2.classList.toggle('fs')); else el2.classList.toggle('fs'); setTimeout(() => { V3.draw(); OCL.pcb.draw(); }, 150); };
  const side = () => { const sd = $('#wb-side'); if (!sd) return; const S = V3.show, c = OCL.findComp(V3.sel || OCL.state.sel);
    sd.innerHTML = `<h4>Layers</h4><div class="layer-grid">${[['top', 'Top copper'], ['bottom', 'Bottom copper'], ['mask', 'Solder mask'], ['silk', 'Silkscreen'], ['comps', 'Component bodies'], ['leads', 'Pins / leads'], ['rats', 'Ratsnest'], ['padlabels', 'Pad labels'], ['grid', 'Grid'], ['axes', 'Axes']].map(([k, l]) => `<label class="chk"><input type="checkbox" data-sh="${k}" ${S[k] ? 'checked' : ''}> ${l}</label>`).join('')}<label class="chk"><input type="checkbox" id="w-lab" ${V3.labels ? 'checked' : ''}> Ref labels</label><label class="chk"><input type="checkbox" id="w-flow" ${V3.flow ? 'checked' : ''}> Signal animation</label></div>
      <div class="row" style="margin-top:6px"><button class="btn sm" id="w-topside">Inspect top</button><button class="btn sm" id="w-botside">Inspect bottom</button></div>
      <h4 style="margin-top:12px">Component transparency</h4><input type="range" class="slider" id="w-alpha" min="0.1" max="1" step="0.05" value="${V3.alpha}">
      <h4>Exploded view</h4><input type="range" class="slider" id="w-sl" min="0" max="1" step="0.01" value="${V3.explode}">
      ${c ? (() => { const d = OCL.defs[c.type], pt = OCL.state.project.pcb.parts.find(p => p.cid === c.id); if (d.offboard || !pt) return `<h4>Selected</h4><p><b>${esc(c.ref)}</b> — off-board (not on the PCB)</p>`; const po = OCL.pinout(c, OCL.fpKey(c, pt)), nl = OCL.netlist();
        return `<h4>Selected: ${esc(c.ref)}</h4><p class="small muted">${esc((OCL.parts[c.part] || {}).name || d.name)} · ${esc(OCL.pcb.fpFor(c, pt).name)}</p><table class="ptable"><tr><th>Pad</th><th>Name</th><th>Net</th></tr>${po.pads.map(p => `<tr class="click" data-wpad="${p.num}"><td class="mono">${p.num}${p.num === 1 ? ' ●' : ''}</td><td class="mono">${esc(p.name)}</td><td class="mono small">${p.pin ? esc(nl.nets[nl.nodeOf[c.id + ':' + p.pin]].name) : p.implicit ? 'implicit' : 'NC'}</td></tr>`).join('')}</table><button class="btn sm" id="w-ds" style="margin-top:6px">Datasheet</button>`; })() : '<p class="small muted" style="margin-top:10px">Click a part or pad to inspect it.</p>'}
      <h4 style="margin-top:12px">Trace my circuit</h4><div id="wb-trace">${OCL.trace.panelHTML()}</div>`;
    $$('[data-sh]', sd).forEach(i => i.onchange = () => { V3.show[i.dataset.sh] = i.checked; V3.draw(); });
    $('#w-lab').onchange = e => { V3.labels = e.target.checked; V3.draw(); }; $('#w-flow').onchange = e => { V3.flow = e.target.checked; V3.draw(); };
    $('#w-topside').onclick = () => { Object.assign(V3.show, { top: true, bottom: false, comps: true, leads: true, silk: true }); V3.setView('top'); side(); };
    $('#w-botside').onclick = () => { Object.assign(V3.show, { top: false, bottom: true, comps: false, silk: false }); V3.setView('bottom'); side(); };
    $('#w-alpha').oninput = e => { V3.alpha = +e.target.value; V3.draw(); }; $('#w-sl').oninput = e => { V3.explode = +e.target.value; V3.draw(); };
    $$('[data-wpad]', sd).forEach(r => r.onclick = () => { const p = OCL.pinout(c, OCL.fpKey(c, OCL.state.project.pcb.parts.find(q => q.cid === c.id))).pads[+r.dataset.wpad - 1]; if (p.pin) OCL.trace.start(c.id, p.pin); else OCL.toast(`Pad ${p.num} (${p.name}) has no schematic connection`); });
    if ($('#w-ds')) $('#w-ds').onclick = () => OCL.modal({ title: 'Datasheet — ' + c.ref, body: UI.datasheetHTML(c.part, c), wide: true });
    OCL.trace.bindPanel($('#wb-trace')); };
  UI.wbSide = side; side();
  if (!UI._wbHooks) { UI._wbHooks = true; const upd = () => { if (OCL.state.view === 'workbench' && UI.wbSide) UI.wbSide(); };
    OCL.on('explode', v => { const s2 = $('#w-sl'); if (s2) s2.value = v; }); OCL.on('pick3d', upd); OCL.on('trace', () => { upd(); if (OCL.state.view === 'workbench') OCL.pcb.draw(); }); OCL.on('selection', upd); OCL.on('pcbchange', () => { if (OCL.state.view === 'workbench') { OCL.pcb.draw(); } }); }
};

/* ---------------- AI COPILOT ---------------- */
V.copilot = host => {
  host.classList.add('full');
  host.innerHTML = `<div style="position:absolute;inset:0;display:grid;grid-template-columns:1fr 340px"><div class="chat"><div class="pane-h"><h3 style="margin:0" class="grow">${I('bot')} AI Engineering Copilot</h3><span class="engine-badge">Local rule-based engine · no external AI connected</span>
      <div class="seg" id="cp-lvl">${['beginner', 'diploma', 'advanced'].map(l => `<button data-l="${l}" class="${OCL.state.settings.level === l ? 'on' : ''}">${l[0].toUpperCase() + l.slice(1)}</button>`).join('')}</div></div>
      <div class="chat-log" id="cp-log"></div><div class="chat-in"><input class="inp" id="cp-q" placeholder="Ask: “Review my circuit”, “LED resistor 12V blue”, “Why is my amplifier saturating?”"><button class="btn primary" id="cp-go">Ask</button></div></div>
    <div class="pane-b" style="border-left:1px solid var(--line);background:var(--bg2)"><h4>Try asking</h4>${['Review my circuit', 'Why is my transistor not switching?', 'Why is my amplifier saturating?', 'Identify possible short circuits', 'Find floating inputs', 'Explain each component', 'Design a 5V regulated power supply', 'Help me build an ECG signal conditioning circuit', 'Suggest a suitable instrumentation amplifier', 'LED resistor 9V red', 'Divider 12V to 3.3V', 'RC cutoff 10k 100n', 'INA gain 101', '555 RA 10k RB 68k C 10u'].map(q => `<div class="part" data-q="${esc(q)}" style="cursor:pointer">${esc(q)}</div>`).join('')}
      <div style="margin-top:16px" class="note-box small">${OCL.copilot.API_ARCH}</div></div></div>`;
  const log = $('#cp-log'); const add = (cls, html, acts = []) => { const m = el(`<div class="msg ${cls}">${html}${acts.length ? '<div class="acts"></div>' : ''}</div>`); acts.forEach(a => { const b = el(`<button class="btn sm">${esc(a.label)}</button>`); b.onclick = a.act; m.querySelector('.acts').appendChild(b); }); log.appendChild(m); log.scrollTop = 1e9; };
  if (!OCL.copilot.history.length) add('a', `Hello! I can see <b>${esc(OCL.state.project.name)}</b> (${OCL.allComponents().length} parts). I analyse your actual netlist, simulation results and validation report using engineering rules and formulas. Ask me to review the design, troubleshoot, or calculate values.`);
  OCL.copilot.history.forEach(h => { add('u', esc(h.q)); add('a', h.r.html, h.r.actions); });
  const go = q => { q = q || $('#cp-q').value; if (!q.trim()) return; add('u', esc(q)); const r = OCL.copilot.ask(q); add('a', r.html, r.actions); $('#cp-q').value = ''; };
  $('#cp-go').onclick = () => go(); $('#cp-q').onkeydown = e => { if (e.key === 'Enter') go(); }; $$('[data-q]', host).forEach(d => d.onclick = () => go(d.dataset.q));
  $$('#cp-lvl button').forEach(b => b.onclick = () => { OCL.state.settings.level = b.dataset.l; UI.saveSettings(); $$('#cp-lvl button').forEach(x => x.classList.toggle('on', x === b)); });
};

/* ---------------- ENGINEERING NOTEBOOK ---------------- */
const DOC = [['title', 'Project title'], ['problem', 'Problem statement'], ['objective', 'Design objective'], ['requirements', 'Requirements'], ['block', 'Block diagram (text; templates add a diagram automatically)'], ['schematic', 'Circuit schematic (auto-inserted from the designer) — notes'], ['selection', 'Component selection (BOM auto-inserted) — rationale'], ['calcs', 'Calculations'], ['simresults', 'Simulation results — observations'], ['validation', 'Validation report (auto) — comments'], ['limitations', 'Limitations'], ['recommendations', 'Recommendations']];
const NTYPES = ['note', 'calculation', 'assumption', 'fault', 'troubleshooting', 'observation', 'simulation result', 'documentation'];
V.notebook = host => {
  const p = OCL.state.project; p.doc = p.doc || {};
  host.innerHTML = `<div class="page" style="max-width:1400px"><div class="row wrap"><h2 class="grow">Engineering Notebook — ${esc(p.name)}</h2><button class="btn" id="nb-rev">${I('save')} Save design revision</button><button class="btn" id="nb-json">${I('export')} Export notebook (JSON)</button><button class="btn primary" id="nb-rep">${I('book')} Generate report</button></div>
    <div class="nb-layout"><div><div class="card"><h3>New entry</h3><div class="grid g2"><label class="fld"><span>Type</span><select class="inp" id="nb-t">${NTYPES.map(t => `<option>${t}</option>`).join('')}</select></label><label class="fld"><span>Attach to component</span><select class="inp" id="nb-c"><option value="">— project —</option>${OCL.allComponents().filter(c => !['ground', 'label', 'vcc', 'junction'].includes(c.type)).map(c => `<option>${esc(c.ref)}</option>`).join('')}</select></label></div>
      <textarea class="inp" id="nb-x" rows="4" placeholder="Record notes, calculations, assumptions, faults, observations…"></textarea><div class="row" style="margin-top:8px"><button class="btn primary sm" id="nb-add">Add entry</button><button class="btn sm" id="nb-sim" ${OCL.sim.readings ? '' : 'disabled'}>Insert current simulation results</button></div></div>
      <h3 style="margin-top:18px">Entries (${p.notes.length})</h3><div id="nb-list">${p.notes.map(n => `<div class="entry"><div class="meta"><span class="pill">${esc(n.type)}</span>${n.comp ? `<span class="pill cyan">${esc(n.comp)}</span>` : ''}<span>${new Date(n.at).toLocaleString()}</span><span class="sp"></span><button class="icon-btn" data-del="${n.id}" title="Delete">${I('trash')}</button></div><div style="white-space:pre-wrap;margin-top:6px">${esc(n.text)}</div></div>`).join('') || '<div class="empty">No entries yet.</div>'}</div>
      <h3 style="margin-top:18px">Design revisions (${p.revisions.length})</h3>${p.revisions.map((r, i) => `<div class="li"><div class="grow"><b>Rev ${p.revisions.length - i}</b> — ${esc(r.note)}<div class="small muted">${new Date(r.at).toLocaleString()} · ${r.parts} parts</div></div><button class="btn sm" data-rest="${i}">Restore</button></div>`).join('') || '<div class="empty">No revisions saved.</div>'}</div>
    <div class="card"><h3>Documentation template</h3><p class="muted small">These 12 sections form the exported engineering report. Schematic, BOM, simulation and validation sections are filled automatically.</p>${DOC.map(([k, l], i) => `<label class="fld"><span>${i + 1}. ${l}</span><textarea class="inp" rows="${k === 'title' ? 1 : 2}" data-d="${k}">${esc(p.doc[k] || '')}</textarea></label>`).join('')}</div></div></div>`;
  $$('[data-d]', host).forEach(t => t.onchange = () => { p.doc[t.dataset.d] = t.value; OCL.emit('dirty'); });
  $('#nb-add').onclick = () => { const x = $('#nb-x').value.trim(); if (!x) return OCL.toast('Write something first'); p.notes.unshift({ id: OCL.uid('n'), type: $('#nb-t').value, comp: $('#nb-c').value, text: x, at: Date.now() }); OCL.emit('dirty'); V.notebook(host); };
  $('#nb-sim').onclick = () => { const R = OCL.sim.readings, nl = OCL.sim.nl; const lines = nl.comps.filter(c => !['ground', 'label', 'vcc', 'junction'].includes(c.type) && R[c.id]).map(c => `${c.ref}: V=${fmt(R[c.id].V, 'V')} I=${fmt(R[c.id].I, 'A')} P=${fmt(Math.abs(R[c.id].P), 'W')}`);
    $('#nb-t').value = 'simulation result'; $('#nb-x').value = `${OCL.sim.mode === 'tran' ? 'Transient, t = ' + fmt(OCL.sim.circuit.S.t, 's') : 'DC operating point'}\n` + lines.join('\n'); };
  $$('[data-del]', host).forEach(b => b.onclick = () => { p.notes = p.notes.filter(n => n.id !== b.dataset.del); OCL.emit('dirty'); V.notebook(host); });
  $('#nb-rev').onclick = async () => { const n = await OCL.prompt('Save design revision', 'Revision note', 'Revision ' + (p.revisions.length + 1)); if (n === null) return; p.revisions.unshift({ note: n || 'Revision', at: Date.now(), parts: OCL.allComponents().length, sheets: OCL.clone(p.sheets), pcb: OCL.clone(p.pcb) }); p.revisions = p.revisions.slice(0, 20); OCL.emit('dirty'); V.notebook(host); OCL.toast('Revision saved (remember to Save the project)', 'ok'); };
  $$('[data-rest]', host).forEach(b => b.onclick = async () => { const r = p.revisions[+b.dataset.rest]; if (!(await OCL.confirm('Restore revision', `Replace the current schematic with “${r.note}”? (You can undo.)`, 'Restore'))) return; OCL.history.push(); p.sheets = OCL.clone(r.sheets); p.pcb = OCL.clone(r.pcb); OCL.state.sheet = 0; OCL.emit('circuit'); OCL.toast('Revision restored', 'ok'); });
  $('#nb-json').onclick = () => OCL.exportText(p.name.replace(/\W+/g, '_') + '-notebook.json', JSON.stringify({ project: p.name, doc: p.doc, notes: p.notes, revisions: p.revisions.map(r => ({ note: r.note, at: r.at, parts: r.parts })) }, null, 1), 'application/json');
  $('#nb-rep').onclick = () => UI.report();
};

/* ---------------- LEARNING CENTRE ---------------- */
UI.lesson = 'divider'; UI.done = {};
V.learning = host => {
  const t = OCL.templates[UI.lesson], lv = OCL.state.settings.level, done = UI.done[t.key] = UI.done[t.key] || new Set(), loaded = OCL.state.project.template === t.key;
  const L = (b, d, a) => ({ beginner: b, diploma: d, advanced: a }[lv]);
  const steps = [
    ['Identify the engineering problem', t.summary, L('What should this circuit do? Say it in one sentence.', 'Write a problem statement with the measurable outcome.', 'Define the problem, operating environment, risk class and applicable standards.')],
    ['Define inputs and outputs', 'Inputs: ' + t.blocks[0] + ' · Output: ' + t.blocks[t.blocks.length - 1], L('List what goes in and what comes out.', 'Specify signal ranges, frequencies, impedances and supply limits.', 'Add accuracy, noise, bandwidth and fault-tolerance requirements.')],
    ['Create the block diagram', null, L('Each box does one job.', 'Show the signal chain and power domains.', 'Partition into isolation domains and identify safety-critical blocks.'), () => OCL.blockDiagramSVG(t.blocks)],
    ['Select electronic components', 'See the component list and datasheets.', L('Pick parts from the library.', 'Check voltage, current and power ratings with margin.', 'Consider tolerance, temperature coefficient, noise and availability.'), null, [['Open component library', () => UI.show('library')]]],
    ['Determine component values', null, L('Use the formulas below.', 'Show each calculation with units.', 'Include tolerance stack-up and worst-case analysis.'), () => `<ul>${t.calcs.map(c => `<li>${esc(c)}</li>`).join('')}</ul>`],
    ['Design the circuit schematic', 'Load the reference schematic and study each connection.', L('Open it and look at each wire.', 'Trace the signal from input to output.', 'Review grounding, decoupling and return paths.'), null, [['Load schematic', () => UI.openTemplate(t.key).then(() => { UI.show('learning'); })]]],
    ['Connect the circuit', 'In the designer: click a pin, then another pin. Use net labels to keep it tidy.', L('Every part needs a complete loop back to ground.', 'Check there are no unconnected (red) pins.', 'Minimise loop areas in the eventual layout.'), null, [['Open designer', () => UI.show('designer')]]],
    ['Run validation', 'Use the Prototype Validation checker before simulating.', L('Fix anything marked red.', 'Resolve critical and high findings.', 'Review the unsupported-check list and plan bench tests for them.'), null, [['Run validation', () => { if (!loaded) return OCL.toast('Load the schematic first (step 6)', 'warn'); UI.runValidation(); }]]],
    ['Simulate the circuit', 'Press Run Simulation.', L('Watch the numbers appear.', 'Compare simulated values with your calculations.', 'Investigate any discrepancy above model tolerance.'), null, [['Run simulation', () => { if (!loaded) return OCL.toast('Load the schematic first (step 6)', 'warn'); UI.show('designer'); OCL.sim.run(); UI.showBottom('scope'); }]]],
    ['Observe readings and waveforms', 'Use the oscilloscope and readings tabs; probe any wire.', L('Look at the waveform shape.', 'Measure Vpp, frequency and DC levels.', 'Check transient response and saturation margins.'), null, [['Show oscilloscope', () => UI.showBottom('scope')]]],
    ['Inspect the 3D model', 'See the assembled board and its exploded view.', L('Spin it around!', 'Identify each component and its pins.', 'Review component heights, clearances and assembly order.'), null, [['Open 3D workbench', () => UI.show('workbench')]]],
    ['Document the prototype', 'Record results, limitations and recommendations; export the report.', L('Write what you learned.', 'Complete all 12 documentation sections.', 'Include verification evidence and a risk summary.'), null, [['Open notebook', () => UI.show('notebook')]]]
  ];
  host.innerHTML = `<div class="page" style="max-width:1300px"><div class="row wrap"><h2 class="grow">Learning Centre</h2><div class="seg" id="lc-lvl">${['beginner', 'diploma', 'advanced'].map(l => `<button data-l="${l}" class="${lv === l ? 'on' : ''}">${l[0].toUpperCase() + l.slice(1)}</button>`).join('')}</div></div>
    <div class="med-layout"><div class="med-list">${OCL.LESSON_KEYS.map(k => { const x = OCL.templates[k], d = (UI.done[k] || new Set()).size; return `<div class="card click ${k === t.key ? 'on' : ''}" data-k="${k}"><b>${esc(x.title.replace('Lesson: ', ''))}</b><div class="small muted">${esc(x.tag)} · ${d}/12 steps</div></div>`; }).join('')}</div>
    <div class="card"><h2 style="margin:0">${esc(t.title)}</h2><p class="muted">${esc(t.principle)}</p>${t.medical ? OCL.SAFETY_HTML : ''}${loaded ? '<span class="pill sim">schematic loaded</span>' : '<span class="pill">schematic not loaded — step 6</span>'}
      <div class="steps">${steps.map((s, i) => `<div class="step ${done.has(i) ? 'done' : ''}"><div class="num" data-s="${i}" title="Mark complete" style="cursor:pointer">${done.has(i) ? '✓' : i + 1}</div><div><b>STEP ${i + 1}: ${esc(s[0])}</b>${s[1] ? `<p class="small">${esc(s[1])}</p>` : ''}${s[3] ? s[3]() : ''}<p class="small muted"><i>${lv[0].toUpperCase() + lv.slice(1)}:</i> ${esc(s[2])}</p>${(s[4] || []).map((a, j) => `<button class="btn sm" data-a="${i}:${j}">${esc(a[0])}</button>`).join(' ')}</div></div>`).join('')}</div></div></div></div>`;
  $$('.med-list .card', host).forEach(c => c.onclick = () => { UI.lesson = c.dataset.k; V.learning(host); });
  $$('#lc-lvl button').forEach(b => b.onclick = () => { OCL.state.settings.level = b.dataset.l; UI.saveSettings(); V.learning(host); });
  $$('[data-s]', host).forEach(n => n.onclick = () => { const i = +n.dataset.s; done.has(i) ? done.delete(i) : done.add(i); V.learning(host); });
  $$('[data-a]', host).forEach(b => b.onclick = () => { const [i, j] = b.dataset.a.split(':').map(Number); done.add(i); steps[i][4][j][1](); });
};

/* ---------------- PROJECT MANAGER ---------------- */
V.projects = async host => {
  const all = (await OCL.db.all('projects')).sort((a, b) => b.modified - a.modified);
  host.innerHTML = `<div class="page"><div class="row wrap"><h2 class="grow">Project Manager</h2><button class="btn" id="pm-imp">${I('open')} Import JSON</button><button class="btn primary" id="pm-new">${I('plus')} New project</button></div>
    <p class="muted">Projects are saved in this browser (IndexedDB)${OCL.db.persistent ? '' : ' — <b>storage is unavailable here, so projects last only for this session</b>'}. Export JSON regularly as a backup or to move projects between computers.</p>
    <div class="card"><div class="row"><b class="grow">Current: ${esc(OCL.state.project.name)}</b>${OCL.state.dirty ? '<span class="pill" style="color:var(--warn)">unsaved changes</span>' : ''}<button class="btn sm" id="pm-save">${I('save')} Save</button><button class="btn sm" id="pm-exp">${I('export')} Export JSON</button></div></div>
    <table class="ptable" style="margin-top:14px"><tr><th>Name</th><th>Parts</th><th>Modified</th><th></th></tr>${all.map(p => `<tr><td><b>${esc(p.name)}</b>${p.template ? ` <span class="pill">${esc(p.template)}</span>` : ''}</td><td>${p.sheets.reduce((s, x) => s + x.components.length, 0)}</td><td class="small muted">${new Date(p.modified).toLocaleString()}</td><td style="text-align:right;white-space:nowrap"><button class="btn sm" data-a="open" data-id="${p.id}">Open</button> <button class="btn sm" data-a="dup" data-id="${p.id}">Duplicate</button> <button class="btn sm" data-a="exp" data-id="${p.id}">Export</button> <button class="btn sm danger" data-a="del" data-id="${p.id}">Delete</button></td></tr>`).join('') || '<tr><td colspan="4"><div class="empty">No saved projects yet.</div></td></tr>'}</table>
    <h3 style="margin-top:22px">Start from a template</h3><div class="grid g3">${Object.values(OCL.templates).map(t => `<div class="card click" data-t="${t.key}"><b>${esc(t.title)}</b><div class="small muted">${esc(t.summary)}</div></div>`).join('')}</div></div>`;
  $('#pm-new').onclick = () => UI.newProjectDialog(); $('#pm-save').onclick = async () => { await OCL.saveProject(); V.projects(host); };
  $('#pm-exp').onclick = () => OCL.exportText(OCL.state.project.name.replace(/\W+/g, '_') + '.ocl.json', JSON.stringify(OCL.state.project, null, 1), 'application/json');
  $('#pm-imp').onclick = async () => { const f = await OCL.pickFile('.json,application/json'); if (!f) return; try { const p = OCL.validateProjectJSON(JSON.parse(f.text)); if (all.some(x => x.id === p.id)) p.id = OCL.uid('p'); UI.setProject(p); await OCL.saveProject(true); OCL.toast('Imported ' + p.name, 'ok'); UI.show('designer'); } catch (e) { OCL.toast('Import failed: ' + e.message, 'err', 6000); } };
  $$('[data-t]', host).forEach(c => c.onclick = () => UI.openTemplate(c.dataset.t));
  $$('[data-a]', host).forEach(b => b.onclick = async () => { const p = all.find(x => x.id === b.dataset.id), a = b.dataset.a;
    if (a === 'open') { UI.setProject(OCL.validateProjectJSON(p)); UI.show('designer'); }
    if (a === 'dup') { const c = OCL.clone(p); c.id = OCL.uid('p'); c.name += ' (copy)'; c.modified = Date.now(); await OCL.db.put('projects', c.id, c); V.projects(host); }
    if (a === 'exp') OCL.exportText(p.name.replace(/\W+/g, '_') + '.ocl.json', JSON.stringify(p, null, 1), 'application/json');
    if (a === 'del' && await OCL.confirm('Delete project', `Delete “${p.name}” from this browser? This cannot be undone.`, 'Delete', true)) { await OCL.db.del('projects', p.id); V.projects(host); } });
};

/* ---------------- SETTINGS & ABOUT ---------------- */
V.settings = host => {
  const s = OCL.state.settings;
  host.innerHTML = `<div class="page"><div class="hero" style="padding:22px"><h1><span>OMAR CIRCUIT LAB</span> <span class="pill cyan" style="vertical-align:middle">v${OCL.VERSION}</span></h1><p style="margin:0;color:var(--ink2)">Medical Engineering Design &amp; Simulation Studio</p><p class="signature" style="margin-top:8px">Designed &amp; Developed by <b>Eng. Omar Abdalla</b> · KMTC Makindu Campus</p></div>
    <div class="grid g2"><div class="card"><h3>${I('shield')} Security</h3><label class="fld"><span>Current password</span><input type="text" autocomplete="off" id="st-o" class="inp secret"></label><label class="fld"><span>New password (min. 8)</span><input type="text" autocomplete="off" id="st-n" class="inp secret"></label><label class="fld"><span>Confirm new password</span><input type="text" autocomplete="off" id="st-c" class="inp secret"></label><div class="row"><button class="btn primary sm" id="st-chg">Change password</button><button class="btn sm" id="st-lock">${I('lock')} Lock now</button></div>
      <label class="fld" style="margin-top:12px"><span>Inactivity lock</span><select class="inp" id="st-idle">${[0, 5, 10, 15, 30, 60].map(m => `<option value="${m}" ${+s.inactivityMin === m ? 'selected' : ''}>${m ? m + ' minutes' : 'Off'}</option>`).join('')}</select></label>
      <div class="note-box small" style="margin-top:10px"><b>What this protection does — and doesn’t.</b> The password is hashed with PBKDF2-SHA-256 (210 000 iterations, random salt) via the Web Crypto API; no plaintext is stored. It stops casual access to the workspace on this device. It <b>cannot</b> protect the application’s source code or stored data from someone with access to the browser’s developer tools or files — any client-side app is inspectable. For confidential IP use the deployment model below.</div></div>
    <div class="card"><h3>${I('gear')} Preferences</h3><label class="fld"><span>Explanation level</span><select class="inp" id="st-lvl">${['beginner', 'diploma', 'advanced'].map(l => `<option ${s.level === l ? 'selected' : ''}>${l}</option>`).join('')}</select></label><label class="fld"><span>Show node voltages on schematic</span><select class="inp" id="st-v"><option value="1" ${s.showVolts ? 'selected' : ''}>On</option><option value="0" ${!s.showVolts ? 'selected' : ''}>Off</option></select></label>
      <h3 style="margin-top:16px">Storage</h3><p class="small">${OCL.db.persistent ? 'Projects, custom parts and settings are stored locally in IndexedDB.' : 'IndexedDB unavailable — data lasts only for this session.'}</p><button class="btn sm danger" id="st-reset">Erase all local data…</button></div></div>
    <div class="grid g2" style="margin-top:14px"><div class="card"><h3>Architecture</h3><ul class="small"><li><b>core.js</b> — state, undo/redo, IndexedDB storage, Web Crypto security</li><li><b>library.js</b> — symbols, pins, parameters, simulation builders, parts catalog &amp; datasheets</li><li><b>sim.js</b> — netlist extraction and MNA engine (Newton–Raphson, source/gmin stepping, backward-Euler transient), time-sliced to keep the UI responsive</li><li><b>validate.js</b> — circuit health checker</li><li><b>editor.js</b> — SVG schematic editor</li><li><b>pcb.js</b> — footprints, routing, DRC, Gerber/Excellon/BOM</li><li><b>view3d.js</b> — dependency-free 3D renderer &amp; exploded views</li><li><b>copilot.js</b> — local rule-based engineering assistant</li><li><b>medical.js</b> — templates and documentation</li><li><b>ui.js / pages.js</b> — interface</li></ul></div>
    <div class="card"><h3>Offline use &amp; deployment</h3><ul class="small"><li><b>Offline:</b> the app has no runtime dependencies besides optional Google Fonts (falls back to system fonts). Unzip the package and open <span class="mono">index.html</span> in Chrome or Edge, or serve the folder with any static server (<span class="mono">python -m http.server</span>). Web Crypto requires HTTPS, localhost or a file:// page in Chromium.</li><li><b>Fonts offline:</b> download Inter &amp; JetBrains Mono .woff2 into <span class="mono">fonts/</span> and replace the Google Fonts link with local @font-face rules.</li><li><b>Secure desktop deployment (recommended for IP protection):</b> package with Electron/Tauri, enable code signing, ship minified/obfuscated bundles, and store projects in an encrypted local database keyed from the user password (AES-GCM via PBKDF2/Argon2).</li><li><b>Server deployment:</b> host behind authenticated HTTPS (institutional SSO), keep projects in a server database with per-user access control and audit logs; run the AI proxy server-side.</li></ul></div></div>
    <div class="card" style="margin-top:14px">${OCL.copilot.API_ARCH}</div>
    <div class="card" style="margin-top:14px"><h3>Planned — not yet implemented</h3><ul class="small"><li>SPICE model import and validated SPICE-level device models</li><li>Switching-converter (buck/boost) simulation, SCR/TRIAC/IGBT models</li><li>Firmware execution for microcontrollers</li><li>Copper pours, solder-mask, silkscreen text and paste layers in Gerber export; boards with more than 2 layers</li><li>STEP/3D model export</li><li>External AI model integration (architecture above)</li><li>Direct PDF generation (use the HTML report + browser “Save as PDF” today)</li></ul></div>
    <p class="signature" style="text-align:center;margin-top:20px">OMAR CIRCUIT LAB · Designed &amp; Developed by <b>Eng. Omar Abdalla</b> · KMTC Makindu Campus</p></div>`;
  $('#st-chg').onclick = async () => { const o = $('#st-o').value, n = $('#st-n').value; if (n.length < 8) return OCL.toast('New password needs at least 8 characters', 'warn'); if (n !== $('#st-c').value) return OCL.toast('Passwords do not match', 'warn'); { const ok = await OCL.auth.change(o, n); OCL.toast(ok ? 'Password changed' : 'Current password is incorrect', ok ? 'ok' : 'err'); } ['#st-o', '#st-n', '#st-c'].forEach(x => $(x).value = ''); };
  $('#st-lock').onclick = UI.lock; $('#st-idle').onchange = e => { s.inactivityMin = +e.target.value; UI.saveSettings(); OCL.toast(s.inactivityMin ? `Will lock after ${s.inactivityMin} min of inactivity` : 'Inactivity lock off'); };
  $('#st-lvl').onchange = e => { s.level = e.target.value; UI.saveSettings(); }; $('#st-v').onchange = e => { s.showVolts = e.target.value === '1'; UI.saveSettings(); };
  $('#st-reset').onclick = async () => { if (await OCL.confirm('Erase all local data', 'Deletes the password, all projects, custom parts and settings from this browser. Export anything you need first.', 'Erase everything', true)) { indexedDB.deleteDatabase('omar-circuit-lab'); location.reload(); } };
};
})();
